// Reproduce with @ethereumjs/vm 10.1.0 installed beside this file.
// node hartii_amm_runtime_vm.mjs /absolute/path/hartii_amm_runtime_evidence.json
import {readFileSync} from 'node:fs';
import assert from 'node:assert/strict';
import {createVM} from '@ethereumjs/vm';
import {Common,Mainnet,Hardfork} from '@ethereumjs/common';
import {Account,createAddressFromString,hexToBytes,bytesToHex} from '@ethereumjs/util';
import {keccak256} from 'ethereum-cryptography/keccak.js';
const fixture=JSON.parse(readFileSync(process.argv[2]));
const runtime=[{result:fixture.factory.runtime},{result:fixture.router.runtime}];
const pairState=[{result:fixture.pair.runtime},{result:'0x'+fixture.token.address.slice(2).padStart(64,'0')},{result:'0x'+fixture.wquai.address.slice(2).padStart(64,'0')}];
const tokenState=[{}, {result:fixture.wquai.runtime}, ...fixture.pair.storage.map(s=>({id:s.slot+10,result:s.value}))];
const word=n=>BigInt(n).toString(16).padStart(64,'0');
const addr=s=>createAddressFromString(s.toLowerCase());
const router=addr('0x000284FD8Df039CFF2949b62D854dc43c2Eae6E1');
const factory=addr('0x000993E799424EEB1f1d6AdAa0e68006f4C696Fe');
const pair=addr('0x002a035cf395e806296A4C049d459acF6411B4EC');
const token=addr('0x'+pairState[1].result.slice(-40));
const wquai=addr('0x'+pairState[2].result.slice(-40));
const sender=addr('0x0000000000000000000000000000000000000099');
const recipient=addr('0x0000000000000000000000000000000000000098');
const selector=s=>bytesToHex(keccak256(new TextEncoder().encode(s))).slice(2,10);
const hash=code=>bytesToHex(keccak256(hexToBytes(code)));
assert.equal(hash(runtime[0].result),'0x5921f7e274335dc1d0a6076079acf41461927b341702efa8271f0e58bc8c78f1');
assert.equal(hash(runtime[1].result),'0x6150c2a53eeccb818146583059319fa94b77c2399705374359eaeeee86ea38c1');
for(const entry of [fixture.router,fixture.factory,fixture.pair,fixture.wquai])assert.equal(hash(entry.runtime),entry.hash);
const rows=[];
for(const decimals of [6,8,18]) {
 const vm=await createVM({common:new Common({chain:Mainnet,hardfork:Hardfork.Shanghai})});
 for(const a of [router,factory,pair,token,wquai,sender,recipient])await vm.stateManager.putAccount(a,new Account(0n,a===sender?10n**25n:0n));
 for(const [a,code] of [[router,runtime[1].result],[factory,runtime[0].result],[pair,pairState[0].result],[wquai,tokenState[1].result]])await vm.stateManager.putCode(a,hexToBytes(code));
 const tokenCode=fixture.token.runtimes.find(t=>t.decimals===decimals).runtime;
 assert.equal(hash(tokenCode),fixture.token.runtimes.find(t=>t.decimals===decimals).hash);
 await vm.stateManager.putCode(token,hexToBytes(tokenCode));
 const storage=async(a,k,v)=>vm.stateManager.putStorage(a,hexToBytes('0x'+word(k)),hexToBytes('0x'+word(v)));
 const mapping=(key,slot)=>keccak256(hexToBytes('0x'+word(BigInt(key.toString()))+word(slot)));
 await storage(router,0,BigInt(factory.toString())); await storage(router,1,BigInt(wquai.toString()));
 const r0=1000000n*10n**BigInt(decimals),r1=1000n*10n**18n,lp=10n**18n;
 for(const row of tokenState.filter(x=>x.id>=10))await vm.stateManager.putStorage(pair,hexToBytes('0x'+word(row.id-10)),hexToBytes(row.result));
 await storage(pair,0,lp);await storage(pair,8,r0+(r1<<112n));await storage(pair,11,0);await storage(pair,12,1);
 await vm.stateManager.putStorage(pair,mapping(sender,1),hexToBytes('0x'+word(lp)));
 for(const [a,b] of [[token,wquai],[wquai,token]]) {const key=keccak256(hexToBytes('0x'+word(BigInt(b.toString()))+bytesToHex(mapping(a,4)).slice(2)));await vm.stateManager.putStorage(factory,key,hexToBytes('0x'+word(BigInt(pair.toString()))));}
 async function call(to,sig,args=[],value=0n,revert=false){const r=await vm.evm.runCall({to,caller:sender,origin:sender,gasLimit:30000000n,value,data:hexToBytes('0x'+selector(sig)+args.map(word).join(''))});if(revert){assert.ok(r.execResult.exceptionError,`${sig} should revert`);return r;}assert.equal(r.execResult.exceptionError,undefined,`${sig}: ${bytesToHex(r.execResult.returnValue)}`);return r;}
 const balance=async(to,owner)=>BigInt(bytesToHex((await call(to,'balanceOf(address)',[BigInt(owner.toString())])).execResult.returnValue));
 await call(token,'mint(address,uint256)',[BigInt(pair.toString()),r0]);await call(token,'mint(address,uint256)',[BigInt(sender.toString()),r0]);
 await call(wquai,'deposit()',[],r1*3n);await call(wquai,'transfer(address,uint256)',[BigInt(pair.toString()),r1]);
 const path=[BigInt(wquai.toString()),BigInt(token.toString())];
 const input=10n**18n;
 const quote=await call(router,'getAmountsOut(uint256,address[])',[input,64,2,...path]);
 const quoted=BigInt('0x'+bytesToHex(quote.execResult.returnValue).slice(-64));
 await call(router,'swapExactETHForTokens(uint256,address[],address,uint256)',[quoted+1n,128,BigInt(recipient.toString()),2n**64n,2,...path],input,true);
 const before=await balance(token,recipient);
 await call(router,'swapExactETHForTokens(uint256,address[],address,uint256)',[quoted,128,BigInt(recipient.toString()),2n**64n,2,...path],input);
 assert.equal((await balance(token,recipient))-before,quoted);
 await call(token,'approve(address,uint256)',[BigInt(router.toString()),r0]);await call(wquai,'approve(address,uint256)',[BigInt(router.toString()),r1]);
 const tokenIn=10n**BigInt(decimals),reverse=path.slice().reverse();
 const sellQuote=await call(router,'getAmountsOut(uint256,address[])',[tokenIn,64,2,...reverse]);
 const nativeOut=BigInt('0x'+bytesToHex(sellQuote.execResult.returnValue).slice(-64));
 await call(router,'swapExactTokensForETH(uint256,uint256,address[],address,uint256)',[tokenIn,nativeOut+1n,160,BigInt(recipient.toString()),2n**64n,2,...reverse],0n,true);
 const nativeBefore=(await vm.stateManager.getAccount(recipient)).balance;
 await call(router,'swapExactTokensForETH(uint256,uint256,address[],address,uint256)',[tokenIn,nativeOut,160,BigInt(recipient.toString()),2n**64n,2,...reverse]);
 assert.equal((await vm.stateManager.getAccount(recipient)).balance-nativeBefore,nativeOut);
 const exact=10n**15n;
 const exactQuote=await call(router,'getAmountsIn(uint256,address[])',[exact,64,2,...reverse]);
 const exactWords=bytesToHex(exactQuote.execResult.returnValue).slice(2).match(/.{64}/g);
 const needed=BigInt('0x'+exactWords[2]);
 await call(router,'swapTokensForExactTokens(uint256,uint256,address[],address,uint256)',[exact,needed-1n,160,BigInt(recipient.toString()),2n**64n,2,...reverse],0n,true);
 const payBefore=await balance(token,sender), receiveBefore=await balance(wquai,recipient);
 await call(router,'swapTokensForExactTokens(uint256,uint256,address[],address,uint256)',[exact,needed+100n,160,BigInt(recipient.toString()),2n**64n,2,...reverse]);
 assert.equal(payBefore-await balance(token,sender),needed); assert.equal(await balance(wquai,recipient)-receiveBefore,exact);
 const nativeExact=10n**BigInt(decimals);
 const nativeQuote=await call(router,'getAmountsIn(uint256,address[])',[nativeExact,64,2,...path]);
 const nativeWords=bytesToHex(nativeQuote.execResult.returnValue).slice(2).match(/.{64}/g);
 const nativeNeeded=BigInt('0x'+nativeWords[2]);
 const nativePayBefore=(await vm.stateManager.getAccount(sender)).balance, nativeTokenBefore=await balance(token,recipient);
 await call(router,'swapETHForExactTokens(uint256,address[],address,uint256)',[nativeExact,128,BigInt(recipient.toString()),2n**64n,2,...path],nativeNeeded+10n**17n);
 assert.equal(nativePayBefore-(await vm.stateManager.getAccount(sender)).balance,nativeNeeded,'unused native cap is refunded immediately');
 assert.equal(await balance(token,recipient)-nativeTokenBefore,nativeExact);
 const lpBefore=await balance(pair,sender);
 await call(router,'addLiquidity(address,address,uint256,uint256,uint256,uint256,address,uint256)',[BigInt(token.toString()),BigInt(wquai.toString()),r0/100n,r1/100n,0,0,BigInt(sender.toString()),2n**64n]);
 const minted=(await balance(pair,sender))-lpBefore;assert.ok(minted>0n);
 await call(pair,'approve(address,uint256)',[BigInt(router.toString()),minted]);
 const tokenBefore=await balance(token,recipient),wrappedBefore=await balance(wquai,recipient);
 await vm.stateManager.checkpoint();
 const remove=await call(router,'removeLiquidity(address,address,uint256,uint256,uint256,address,uint256)',[BigInt(token.toString()),BigInt(wquai.toString()),minted,0,0,BigInt(recipient.toString()),2n**64n]);
 const removed=bytesToHex(remove.execResult.returnValue).slice(2).match(/.{64}/g).map(v=>BigInt('0x'+v));
 await vm.stateManager.revert();
 await call(router,'removeLiquidity(address,address,uint256,uint256,uint256,address,uint256)',[BigInt(token.toString()),BigInt(wquai.toString()),minted,removed[0]+1n,removed[1],BigInt(recipient.toString()),2n**64n],0n,true);
 await call(router,'removeLiquidity(address,address,uint256,uint256,uint256,address,uint256)',[BigInt(token.toString()),BigInt(wquai.toString()),minted,...removed,BigInt(recipient.toString()),2n**64n]);
 assert.ok(await balance(token,recipient)>tokenBefore);assert.ok(await balance(wquai,recipient)>wrappedBefore);
 rows.push({decimals,buy:String(quoted),sell:String(nativeOut),minted:String(minted)});
}
assert.deepEqual(rows,fixture.expected);
console.log(JSON.stringify({router:router.toString(),factory:factory.toString(),pair:pair.toString(),cases:rows},null,2));
